const MAP_W=2048,MAP_H=1763;
const PD=[{"id":"acuity-lakefront","name":"Acuity Lakefront","t":"p","g":"land","kind":"landmark","x":828,"y":260,"sum":"A broad white bowl of ice with a dark blue fringe where the shore keeps its water open. After days of wind on the Drift Fields, Acuity feels unnervingly still. People talk quietly here. The ice ticks and booms at night in long, slow phrases.","facts":[["Access","only by Route 217; about 8 days from Greenstation, 4–8 days from Snowpoint"],["Clearance","Vanguard (7+ badges) (reached only by Route 217). Wardens (5+) may come with a Greenstation guide or on a research permit"]],"cx":828,"cy":260,"bb":[758,210,898,310]},{"id":"snowpoint-city","name":"Snowpoint City","t":"p","g":"settle","kind":"city","x":892,"y":202,"sum":"Sinnoh's northernmost city, a stepped town of timber houses, steam vents and warm stone streets at the end of the road. Cheerful, practical and genuinely used to the dark.","facts":[["Gym","Candice · Ice-type · Icicle Badge"]],"cx":892,"cy":202,"bb":[822,152,962,252]},{"id":"mt-stark","name":"Mt. Stark","t":"p","g":"land","kind":"landmark","x":1543,"y":280,"sum":"The island's chimney. Mt. Stark is a restless volcano, its crater lip ringed with yellow rock and steam, its slopes black with cinder and white with salt. The League's volcano watch keeps a station on the rim.","facts":[["Clearance","Vanguard (7+ badges). Wardens (5+) may go with a volcano-watch escort or on a research permit"]],"cx":1543,"cy":280,"bb":[1473,230,1613,330]},{"id":"fullmoon-island","name":"Fullmoon Island","t":"p","g":"land","kind":"island","x":428,"y":312,"sum":"A long pale island with a spine of grey slate, silver-leaved scrub, a shell-white beach and a quiet most visitors describe as \"the kind you can hear.\" Cold, bright and strangely lit even on cloudy nights, it is Sinnoh's best-known legend-island and one of its least visited places.","facts":[["Access","League and Ranger permit only (Moon Islands Conservation Order)"]],"cx":428,"cy":312,"bb":[358,262,498,362]},{"id":"newmoon-island","name":"Newmoon Island","t":"p","g":"land","kind":"island","x":500,"y":364,"sum":"A pale, curved island that sailors steer around. Its bay is the shape of a crescent and its water is unusually still. Ranger charts mark everything within five kilometers of its coast as the League's Closed Water.","facts":[["Access","no landing is permitted under any category; the surrounding sea is the League's Closed Water"]],"cx":500,"cy":364,"bb":[430,314,570,414]},{"id":"greenstation-town","name":"Greenstation Town","t":"p","g":"settle","kind":"town","x":837,"y":432,"sum":"A mountain-pass railhead where four routes meet. It is the last stop of the narrow-gauge Lilypad Line and the first stop of everything harder. In a white landscape, the only green is the station roof.","facts":[],"cx":837,"cy":432,"bb":[767,382,907,482]},{"id":"lilypad-town","name":"Lilypad Town","t":"p","g":"settle","kind":"town","x":960,"y":337,"sum":"A steaming hot-spring town on the snow country's east flank, where open pools never freeze and lily pads float in January. Home of the Steam Hall, a plow depot, and the north's best soup.","facts":[],"cx":960,"cy":337,"bb":[890,287,1030,387]},{"id":"battle-resort-survival-area","name":"Battle Resort Survival Area","t":"p","g":"settle","kind":"area","x":1378,"y":387,"sum":"A League-run wilderness school on the north end of the Battle Resort's west arm: a log palisade, a ten-station course, a lighthouse, and an unshakable rule that nobody here is impressed by your badges.","facts":[],"cx":1378,"cy":387,"bb":[1308,337,1448,437]},{"id":"sandalstraw-town","name":"Sandalstraw Town","t":"p","g":"settle","kind":"town","x":719,"y":585,"sum":"A cold-country craft town of about 5,500 at the north knuckle of the west ring road, famous for woven straw, trail footwear and moon-watching. A Contest Center, a Ranger marine office and a very old straw giant share its small streets.","facts":[],"cx":719,"cy":585,"bb":[649,535,789,635]},{"id":"shelter-town","name":"Shelter Town","t":"p","g":"settle","kind":"town","x":800,"y":500,"sum":"A refuge town built around one rule: nobody is turned away from a storm. Its Long Hall can shelter eight hundred people, and its bell can be heard across the foothills.","facts":[],"cx":800,"cy":500,"bb":[730,450,870,550]},{"id":"iron-island","name":"Iron Island","t":"p","g":"settle","kind":"island","x":438,"y":719,"sum":"A red-brown rock island with one village, two mines and a standing argument about the future. About 1,300 miners, wranglers and families live on it, and a handful of Steelix are closer to colleagues than livestock.","facts":[],"cx":438,"cy":719,"bb":[368,669,508,769]},{"id":"lucario-kingdom","name":"Lucario Kingdom","t":"p","g":"land","kind":"landmark","x":1134,"y":648,"sum":"Six limestone terraces rise from oak and birch forest to a bare plateau above the sea. From Route 226 the massif looks like a stair leading to a throne. Locals call it the Stair; the plateau is the Crown; and the community living on it is the Kingdom.","facts":[["Access","from the Kingdom Gate Post on Route 226; a day to the lower terraces. The upper terraces are closed."]],"cx":1134,"cy":648,"bb":[1064,598,1204,698]},{"id":"battle-resort-fight-area","name":"Battle Resort Fight Area","t":"p","g":"settle","kind":"area","x":1330,"y":611,"sum":"The Resort's arena district: floodlit stadiums, rows of dojos and a public scoreboard that ranks everybody. A city of sparring yards around one great stadium, where reputation is the only currency nobody inflates.","facts":[],"cx":1330,"cy":611,"bb":[1260,561,1400,661]},{"id":"battle-resort-port","name":"Battle Resort Port","t":"p","g":"land","kind":"landmark","x":1588,"y":606,"sum":"The Gate. Everyone and almost everything that enters the Battle Resort comes through Port Head. It is a plain, busy harbor: gray piers, rust-streaked cranes, a stack of fruit crates, and a long low building called the Gate Hall, where staff check passes and Pokémon.","facts":[],"cx":1588,"cy":606,"bb":[1518,556,1658,656]},{"id":"resort-area","name":"Resort Area","t":"p","g":"settle","kind":"area","x":1690,"y":666,"sum":"The Battle Resort's holiday town at the island's southeastern tip: white-sand coves, terraced hotels, a spa fed by volcanic springs, and the people who keep all of it running. Where Sinnoh's winners go to rest, and where those who would like to be mistaken for them go to be seen.","facts":[],"cx":1690,"cy":666,"bb":[1620,616,1760,716]},{"id":"lily-of-the-valley-conference","name":"Lily of the Valley Conference","t":"p","g":"land","kind":"landmark","x":1700,"y":741,"sum":"The Stage. Lily of the Valley is a pretty island with a purpose. The whole of it, a low green hill, a sandy shore and a ring of paths, was cleared and planted for one event: the League's annual public tournament. The rest of the year it is a caretaker's village and a very quiet garden.","facts":[],"cx":1700,"cy":741,"bb":[1630,691,1770,791]},{"id":"squallville","name":"Squallville","t":"p","g":"settle","kind":"town","x":558,"y":771,"sum":"A slate-roofed headland harbor of about 4,000, where the sea weather arrives first and everyone lives by forecast. Fishers, ore haulers and weather-watchers share a harbor too small for all of them.","facts":[],"cx":558,"cy":771,"bb":[488,721,628,821]},{"id":"eterna-forest","name":"Eterna Forest","t":"p","g":"land","kind":"landmark","x":625,"y":795,"sum":"A dense old-growth forest, dim even at noon. The canopy is heavy, the trails narrow, and on a windless day it is among the quietest places in Sinnoh.","facts":[["Clearance","Open on the old forest road. Off it or after dark: Pathfinder (2+ badges), a research permit, or a hired guide"]],"cx":625,"cy":795,"bb":[555,745,695,845]},{"id":"eterna-city","name":"Eterna City","t":"p","g":"settle","kind":"city","x":781,"y":754,"sum":"An old forest-edge city of about 30,000, proud of its history and its greenery. Quieter than Jubilife, older than Hearthome, and a bit stuck in its ways.","facts":[["Gym","Gardenia · Grass-type · Forest Badge"]],"cx":781,"cy":754,"bb":[711,704,851,804]},{"id":"celestic-town","name":"Celestic Town","t":"p","g":"settle","kind":"town","x":1051,"y":768,"sum":"A small, stubborn town of stone houses, wind bells and long memories on Mt. Coronet's east shoulder. Sinnoh's keeper of old stories, and a place that has never once been in a hurry.","facts":[],"cx":1051,"cy":768,"bb":[981,718,1121,818]},{"id":"veilstone-city","name":"Veilstone City","t":"p","g":"settle","kind":"city","x":1498,"y":858,"sum":"A fast-growing coastal city on Sinnoh's eastern cliffs. Department stores, cranes, wind and the sea, with a Gym that still thinks mountains are the best teachers.","facts":[["Gym","Maylene · Fighting-type · Cobble Badge"]],"cx":1498,"cy":858,"bb":[1428,808,1568,908]},{"id":"dandelion-island","name":"Dandelion Island","t":"p","g":"settle","kind":"island","x":1618,"y":870,"sum":"A small island in the east sea, a short ferry hop from Veilstone, where about nine hundred people live among wind-mills, seed vaults and drifting fluff, and where every spring the sky fills with Hoppip.","facts":[],"cx":1618,"cy":870,"bb":[1548,820,1688,920]},{"id":"champions-port","name":"Champion's Port","t":"p","g":"settle","kind":"town","x":1723,"y":894,"sum":"A tidy, nervous harbor town on the southwest shore of the League's island, where every challenger spends three days being patient. The ferry brings hopefuls in; the Pavilion road takes the survivors out.","facts":[],"cx":1723,"cy":894,"bb":[1653,844,1793,944]},{"id":"elite-four-island","name":"Elite Four Island","t":"p","g":"settle","kind":"island","x":1734,"y":854,"sum":"The Pokémon League's headquarters island in the east sea: a small administrative city on a mountain's skirt, where the Elite Four and the Champion work and where Sinnoh's best trainers are tested and recorded.","facts":[],"cx":1734,"cy":854,"bb":[1664,804,1804,904]},{"id":"chocovine-town","name":"Chocovine Town","t":"p","g":"settle","kind":"town","x":457,"y":901,"sum":"A terraced coast town of about 8,000 built on cocoa, Poffins and the memory of a failed vineyard. Warm brick, warm air, and a roasting smell you can follow from three miles away. A Contest Center sits at its heart.","facts":[],"cx":457,"cy":901,"bb":[387,851,527,951]},{"id":"floaroma-flower-fields","name":"Floaroma Flower Fields","t":"p","g":"land","kind":"landmark","x":531,"y":928,"sum":"A gentle quilt of terraced flower beds, dye plots and wild meadow that supplies half of Sinnoh's cut flowers. In summer the whole slope is a color-field: lavender, lily, poppy, marigold and an unreasonable amount of clover. In winter it is brown stubble and quiet fields under snow.","facts":[],"cx":531,"cy":928,"bb":[461,878,601,978]},{"id":"floaroma-town","name":"Floaroma Town","t":"p","g":"settle","kind":"town","x":556,"y":989,"sum":"A flower-and-honey town of a few thousand people, north of Jubilife. Pretty by design, practical underneath. Floaroma lives off flowers, honey, dye plants and herbal remedies. Every wall has a window box, every corner has a planter, and the whole town smells like three different honeys at once.","facts":[],"cx":556,"cy":989,"bb":[486,939,626,1039]},{"id":"valley-windworks","name":"Valley Windworks","t":"p","g":"land","kind":"landmark","x":691,"y":996,"sum":"Sinnoh's largest renewable power complex: two wind ridges and a small pumped-storage reservoir that together supply Jubilife, Floaroma, Eterna and Oreburgh. It is publicly owned, run by the Coronet Valley Power Authority (CVPA), and one of the few places in the region where every citizen thinks the same thing: thank goodness it is there.","facts":[],"cx":691,"cy":996,"bb":[621,946,761,1046]},{"id":"206-bridge","name":"206 Bridge","t":"p","g":"land","kind":"landmark","x":788,"y":931,"sum":"A long steel deck on older stone piers across a river gorge: the single most photographed object on the Cycling Road. The stone is centuries old and part of the original trade road; the deck and cables were added forty years ago, and a glass-floored viewing span was added five years later because tourists would not stop asking for one.","facts":[],"cx":788,"cy":931,"bb":[718,881,858,981]},{"id":"mt-coronet-and-spear-pillar","name":"Mt. Coronet and Spear Pillar","t":"p","g":"land","kind":"landmark","x":938,"y":1001,"sum":"Mt. Coronet is the backbone of Sinnoh and the reason most of its maps have a gap in the middle. It is not one peak but a long, broken massif of cold rock, hanging valleys, glaciers and snowfields, riddled with caves and magnetic ground, and ringed by towns that argue about what it means.","facts":[["Access","the mountain is crossed by three maintained tunnels (Mt. Coronet Pass, the Coronet Spine, Route 207); the summit is closed by League order"],["Clearance","Tunnels: Pathfinder (2+ badges), or a hired guide. Off the marked routes: Warden (5+ badges), or Pathfinders on a research permit with a Ranger escort. Summit: closed to everyone"]],"cx":938,"cy":1001,"bb":[868,951,1008,1051]},{"id":"gracidea-flower-garden","name":"Gracidea Flower Garden","t":"p","g":"land","kind":"landmark","x":1002,"y":1047,"sum":"A bowl of meadow tucked into a fold of the mountain, protected from wind on three sides and open to the south. Sunlight pools there for hours after it has left the valley below. In late spring the whole bowl turns pink, in a bloom that lasts roughly three weeks, and the slopes around it hum.","facts":[["Access","the Meadow Path, about four days on foot from Emeragrove; Garden Society permit required in bloom season"]],"cx":1002,"cy":1047,"bb":[932,997,1072,1097]},{"id":"michina-ruins","name":"Michina Ruins","t":"p","g":"land","kind":"landmark","x":1089,"y":943,"sum":"The Ruins are a stepped complex of stone courts and galleries, cut into the slope above the Mirror Tarn's inlet, with the Old Road running straight into its gate. It is silent most of the day. Visitors tend to lower their voices without being asked.","facts":[["Access","a day on the Pilgrims' Spur from town; open to visitors with a Dig House pass"]],"cx":1089,"cy":943,"bb":[1019,893,1159,993]},{"id":"michina-town","name":"Michina Town","t":"p","g":"settle","kind":"town","x":1119,"y":937,"sum":"A stone-and-wool town in a high bowl on Mt. Coronet's east face, built for the road to the Ruins and still arguing about who the road belongs to.","facts":[],"cx":1119,"cy":937,"bb":[1049,887,1189,987]},{"id":"emeragrove-town","name":"Emeragrove Town","t":"p","g":"settle","kind":"town","x":1154,"y":1037,"sum":"A terraced garden town on the slope above Route 209, famous for its hedges, glasshouses, honey, and an annual festival of saying thank you. The people here are kind, a little competitive, and absolutely certain about compost.","facts":[],"cx":1154,"cy":1037,"bb":[1084,987,1224,1087]},{"id":"solaceon-town","name":"Solaceon Town","t":"p","g":"settle","kind":"town","x":1222,"y":984,"sum":"A quiet valley town of scholars, breeders and travelers. Famous for its Day Care and its ruins, and the hinge on which the Hearthome-to-Veilstone road turns.","facts":[],"cx":1222,"cy":984,"bb":[1152,934,1292,1034]},{"id":"crown-city","name":"Crown City","t":"p","g":"settle","kind":"city","x":1575,"y":1017,"sum":"The richest and most polished city in eastern Sinnoh: white bluffs, a deep harbor, trading houses, private academies and excellent restaurants. It has a very large number of opinions about Gyms and does not have one.","facts":[],"cx":1575,"cy":1017,"bb":[1505,967,1645,1067]},{"id":"canalave-city","name":"Canalave City","t":"p","g":"settle","kind":"city","x":321,"y":1058,"sum":"A canal-cut harbor city of salt wind, steel and old paper. Shipwrights and librarians share one hill and rarely agree on the budget.","facts":[["Gym","Byron · Steel-type · Mine Badge"]],"cx":321,"cy":1058,"bb":[251,1008,391,1108]},{"id":"jubilife-city","name":"Jubilife City","t":"p","g":"settle","kind":"city","x":550,"y":1162,"sum":"Sinnoh's largest city and its primary center for media, technology, communications, commerce, and League administration. Jubilife is fast-growing, ambitious, expensive, noisy, and seemingly always under construction.","facts":[],"cx":550,"cy":1162,"bb":[480,1112,620,1212]},{"id":"alamos-town","name":"Alamos Town","t":"p","g":"settle","kind":"town","x":677,"y":1099,"sum":"A poplar-lined hill town on a small lake, famous for lake-aged cheese, quarry stone and a very stubborn preservation society. Alamos is where Oreburgh's miners go on their rest-week and where Jubilife people go to feel like they are in the country. The town clings to a terraced hillside above the lake, with poplars in rows along every path and cheese caves cut into the quarry wall.","facts":[],"cx":677,"cy":1099,"bb":[607,1049,747,1149]},{"id":"oreburgh-city","name":"Oreburgh City","t":"p","g":"settle","kind":"city","x":774,"y":1172,"sum":"A coal-and-fossil mining city in the south-west, home of Roark and the Coal Badge. Miners, a mining museum and a lot of dust.","facts":[["Gym","Roark · Rock-type · Coal Badge"]],"cx":774,"cy":1172,"bb":[704,1122,844,1222]},{"id":"hearthome-city","name":"Hearthome City","t":"p","g":"settle","kind":"city","x":1124,"y":1120,"sum":"Sinnoh's cultural capital: theaters, Contests, fashion, music and a central plaza that never quite empties. Larger and warmer than Eterna, less corporate than Jubilife.","facts":[["Gym","Fantina · Ghost-type · Relic Badge"]],"cx":1124,"cy":1120,"bb":[1054,1070,1194,1170]},{"id":"majolica-town","name":"Majolica Town","t":"p","g":"settle","kind":"town","x":1223,"y":1165,"sum":"A tile-roofed pottery town of kiln smoke, glazed streets and a Contest hall famous for its trophies. Where Hearthome comes to buy plates and Coordinators come to be seen.","facts":[],"cx":1223,"cy":1165,"bb":[1153,1115,1293,1215]},{"id":"valor-lakefront-and-grand-festival","name":"Valor Lakefront and Grand Festival","t":"p","g":"land","kind":"landmark","x":1519,"y":1200,"sum":"A broad cold lake, a grand old hotel, and the stage where the year's best Coordinators compete for the Grand Festival title. The most glamorous address in the east for one week a year, and a plain, pretty lakeshore for the other fifty-one.","facts":[],"cx":1519,"cy":1200,"bb":[1449,1150,1589,1250]},{"id":"brussel-town","name":"Brussel Town","t":"p","g":"settle","kind":"town","x":1598,"y":1175,"sum":"A ridgeline town of glasshouses and sawmills at the edge of the Brusselwood, where the whole slope glows amber at night and the Contest Hall used to be a greenhouse.","facts":[],"cx":1598,"cy":1175,"bb":[1528,1125,1668,1225]},{"id":"arrowroot-town","name":"Arrowroot Town","t":"p","g":"settle","kind":"town","x":1639,"y":1116,"sum":"A river-mill town that smells of warm starch and baked sugar, where the Poffin ovens are always on and the Contest Hall stage is backed by a working waterwheel.","facts":[],"cx":1639,"cy":1116,"bb":[1569,1066,1709,1166]},{"id":"camellia-town","name":"Camellia Town","t":"p","g":"settle","kind":"town","x":1733,"y":1194,"sum":"A small hill town of tea terraces, camellia-oil presses and a shrine that blooms in the dead of winter. It has no Contest hall and is the quietest rest stop on the eastern peninsula.","facts":[],"cx":1733,"cy":1194,"bb":[1663,1144,1803,1244]},{"id":"sunyshore-city","name":"Sunyshore City","t":"p","g":"settle","kind":"city","x":1791,"y":1166,"sum":"A bright, breezy harbor city that runs on sunlight and argues about it. The last stop before the sea crossings to the Elite Four island and the Conference island, and home to the Gull Badge.","facts":[["Gym","Marina · Flying-type · Gull Badge"]],"cx":1791,"cy":1166,"bb":[1721,1116,1861,1216]},{"id":"verity-lakefront","name":"Verity Lakefront","t":"p","g":"land","kind":"landmark","x":388,"y":1345,"sum":"A broad, shallow, quiet lake in the southwest corner of Sinnoh, ringed with reedbeds and low hills. Twinleaf children grow up swimming and skipping stones here; nearly every famous trainer from the town has a story about the water.","facts":[],"cx":388,"cy":1345,"bb":[318,1295,458,1395]},{"id":"sandgem-town","name":"Sandgem Town","t":"p","g":"settle","kind":"town","x":557,"y":1345,"sum":"A seaside town and home of the Sandgem Pokémon Research Laboratory, now directed by Professor Lydia Hawthorne.","facts":[],"cx":557,"cy":1345,"bb":[487,1295,627,1395]},{"id":"bewilder-forest","name":"Bewilder Forest","t":"p","g":"land","kind":"landmark","x":581,"y":1257,"sum":"A broad belt of old oak and beech woodland that has never been properly surveyed. The Rangers say that is on purpose. It is not a hostile forest: it is confusing, a place where trails split, hollows echo and nobody agrees on which way north is.","facts":[],"cx":581,"cy":1257,"bb":[511,1207,651,1307]},{"id":"grand-marsh","name":"Grand Marsh","t":"p","g":"land","kind":"landmark","x":1124,"y":1345,"sum":"Sinnoh's great wetland: a licensed, guided wildlife area of reed seas, boardwalks, mud flats and drowned orchards, feeding the Pastoria delta. The best place in the region to see out-of-region species living a legal, supervised life.","facts":[["Clearance","Open on the boardwalks. Off them: Pathfinder (2+ badges), a research permit, or a licensed Wetlands Trust guide"]],"cx":1124,"cy":1345,"bb":[1054,1295,1194,1395]},{"id":"safari-zone","name":"Safari Zone","t":"p","g":"land","kind":"landmark","x":1172,"y":1284,"sum":"A fenced, licensed preserve of savanna, rainforest and wetland east of the Grand Marsh, stocked with species from every region. It is the legal home of Sinnoh's out-of-region Pokémon, and the likeliest source when one turns up on a road.","facts":[],"cx":1172,"cy":1284,"bb":[1102,1234,1242,1334]},{"id":"neighborly-town","name":"Neighborly Town","t":"p","g":"settle","kind":"town","x":1541,"y":1240,"sum":"The east's great crossroads and its friendliest address. Five roads meet at a bell tower, strangers are expected to eat at the community table, and the Contest crowd fills every bed in town.","facts":[],"cx":1541,"cy":1240,"bb":[1471,1190,1611,1290]},{"id":"daybreak-town","name":"Daybreak Town","t":"p","g":"settle","kind":"town","x":1753,"y":1261,"sum":"A fishing village at the eastern tip of the peninsula, where the sun first touches Sinnoh and the Contest stage is a headland that faces the dawn.","facts":[],"cx":1753,"cy":1261,"bb":[1683,1211,1823,1311]},{"id":"twinleaf-town","name":"Twinleaf Town","t":"p","g":"settle","kind":"town","x":432,"y":1399,"sum":"A small, quiet town in south-western Sinnoh, at the start of Route 201 and a short walk from Lake Verity.","facts":[],"cx":432,"cy":1399,"bb":[362,1349,502,1449]},{"id":"sandgem-port","name":"Sandgem Port","t":"p","g":"land","kind":"landmark","x":560,"y":1392,"sum":"The southwest's passenger door to the world. Sandgem Port is a working harbor of seven quays, a fish market, a customs shed and a lighthouse on a long breakwater. It handles Oreburgh's ore (via Route 237), Sandgem's fish and berries, and every overseas passenger who prefers a ship to a plane.","facts":[],"cx":560,"cy":1392,"bb":[490,1342,630,1442]},{"id":"pastoria-city","name":"Pastoria City","t":"p","g":"settle","kind":"city","x":1280,"y":1394,"sum":"A delta city of boardwalks, canals and stilted roofs where the Grand Marsh drains into the sea. Rain is the weather, water is the road, and nobody here is surprised by mud.","facts":[["Gym","Klevin · Fairy-type · Ring Badge"]],"cx":1280,"cy":1394,"bb":[1210,1344,1350,1444]},{"id":"sage-town","name":"Sage Town","t":"p","g":"settle","kind":"town","x":928,"y":1598,"sum":"A quiet southern coast town of herb terraces, salt pans and smokehouses, famous for sage bundles, spice blends and a Contest hall that judges cooking as seriously as appeal. Smells of smoke, salt and something green.","facts":[],"cx":928,"cy":1598,"bb":[858,1548,998,1648]},{"id":"south-sinnoh-port","name":"South Sinnoh Port","t":"p","g":"land","kind":"landmark","x":1050,"y":1679,"sum":"The region's main freight and international port, at the far southern tip: cranes, container stacks, a quarantine yard, and a thousand small tales of what came in the hold. Foreign species arrive here, legally and otherwise.","facts":[],"cx":1050,"cy":1679,"bb":[980,1629,1120,1729]},{"id":"route-201","name":"Route 201","t":"r","g":"route","kind":"route","nick":"The First Road","sum":"One of Sinnoh's gentlest trainer routes and, for generations of children from Twinleaf, the first stretch of wilderness that feels truly independent. Most beginners spend a night on it, usually at Willowbank Camp.","facts":[["Connects","Twinleaf Town ↔ Sandgem Town"],["Travel time","4 days on foot"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Verity Ranger Hut, at the Lake Verity turn-off"]],"segs":[[[432,1388],[429,1365],[439,1357],[455,1356],[491,1342],[544,1345],[554,1334],[557,1335]]],"bb":[429,1334,557,1388],"cx":493,"cy":1361},{"id":"route-202","name":"Route 202","t":"r","g":"route","kind":"route","nick":"","sum":"Route 202 is where Sinnoh's beginner journey becomes a real expedition. Leaving Sandgem Town, the route passes through coastal farmland and gradually enters a broad belt of mixed woodland before emerging into the increasingly developed outskirts of Jubilife City. The route is well traveled and maintained, but its length means trainers must manage food, camps, weather, and their Pokémon for several consecutive days.","facts":[["Connects","Sandgem Town ↔ Jubilife City"],["Travel time","6–8 days on foot"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at the League Route House, two-thirds of the way to Jubilife"]],"segs":[[[557,1335],[553,1312],[543,1295],[542,1274],[546,1267],[546,1256],[538,1246],[536,1232],[546,1222],[546,1215],[556,1192],[557,1175],[562,1166],[559,1154],[552,1151]]],"bb":[536,1151,562,1335],"cx":549,"cy":1243},{"id":"route-203","name":"Route 203","t":"r","g":"route","kind":"route","nick":"","sum":"Route 203 is where Sinnoh stops feeling gentle. The farmland east of Jubilife gives out quickly, replaced by scrubland, exposed rock and a haze of mine dust that hangs over the approach to Oreburgh on still days.","facts":[["Connects","Jubilife City ↔ Oreburgh City"],["Travel time","2–4 days on foot"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Oreburgh Gate Ranger Post, at the Oreburgh end"]],"segs":[[[552,1151],[564,1163],[595,1161],[605,1173],[610,1175],[617,1175],[630,1164],[635,1164],[641,1170],[652,1171],[663,1163],[671,1164],[685,1157],[687,1159],[695,1157],[715,1169],[758,1168],[781,1164]]],"bb":[552,1151,781,1175],"cx":666,"cy":1163},{"id":"route-204","name":"Route 204","t":"r","g":"route","kind":"route","nick":"The Flower Road","sum":"The short, gentle stretch where Jubilife's noise fades and the countryside returns. It is the League's easiest second route, heavily patrolled and well signed.","facts":[["Connects","Jubilife City ↔ Floaroma Town"],["Travel time","2 days on foot"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Floaroma Road Ranger Hut, at the Floaroma end"]],"segs":[[[552,1151],[549,1138],[541,1130],[532,1107],[530,1078],[533,1067],[549,1046],[550,1036],[546,1029],[546,1013],[551,1003],[551,988],[558,980]]],"bb":[530,980,558,1151],"cx":544,"cy":1065},{"id":"route-205","name":"Route 205","t":"r","g":"route","kind":"route","nick":"The River Path","sum":"A gentle riverside walk through meadow and light woodland, then the long, dim passage through Eterna Forest. It is the last easy route before the heart of Sinnoh.","facts":[["Connects","Floaroma Town ↔ Eterna Forest ↔ Eterna City"],["Travel time","4 days on foot"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Forest Gate Ranger Post, at the Eterna Forest entrance"]],"segs":[[[558,980],[584,980],[587,977],[587,972],[599,958],[600,945],[605,937],[605,928],[621,902],[628,877],[628,854],[620,831],[618,805],[634,804],[635,792],[631,788],[635,789],[639,786],[650,785],[659,775],[660,763],[668,756],[675,756],[684,766],[686,772],[702,784],[715,787],[732,787],[741,777],[742,757],[750,747],[755,747],[765,755],[788,744],[793,755]],[[558,980],[564,987],[564,996],[583,1006],[612,1007],[631,1014],[671,1016],[684,1005],[698,1004]]],"bb":[558,744,793,1016],"cx":675,"cy":880},{"id":"route-206","name":"Route 206","t":"r","g":"route","kind":"route","nick":"The Cycling Road","sum":"Two lanes of tarmac for wheels and a gravel verge for walkers, laid on a long steady grade down the mountain's western flank. Eterna sits higher than Oreburgh, so southbound riders coast for a day and northbound riders earn every kilometer.","facts":[["Connects","Eterna City ↔ Oreburgh City, via the 206 Bridge"],["Travel time","10–12 days on foot; 4–6 days by bicycle"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Larch Post (Route House); bike patrols on the Cycling Road"]],"segs":[[[793,755],[794,759],[783,770],[783,784],[791,798],[791,822],[796,830],[796,849],[791,859],[791,893],[787,898],[787,917],[796,926],[797,937],[792,943],[792,964],[805,979],[805,988],[798,996],[798,999],[811,1008],[811,1018],[805,1025],[805,1032],[816,1043],[816,1053],[806,1062],[786,1062],[782,1067],[782,1073],[787,1079],[787,1086],[780,1093],[779,1098],[789,1108],[789,1116],[784,1123],[784,1141],[776,1156],[781,1164]]],"bb":[776,755,816,1164],"cx":796,"cy":959},{"id":"route-207","name":"Route 207","t":"r","g":"route","kind":"route","nick":"The Southern Crossing","sum":"A maintained tunnel and cut-through that connects Oreburgh's mining country with Hearthome's meadows. Cooler, darker and louder than Route 211, but far more trafficked: ore haulers, couriers and miners use it daily.","facts":[["Connects","Oreburgh City ↔ Route 208 ↔ Hearthome City"],["Travel time","2–4 days (mostly underground)"],["Danger","★★★☆☆"],["Clearance","Pathfinder (2+ badges), or 0–1 badges with a hired tunnel guide from the Oreburgh portal"],["Ranger station","West Portal Ranger Post, at the Oreburgh tunnel mouth"]],"segs":[[[781,1164],[788,1160],[804,1137],[809,1137],[821,1130],[827,1133],[831,1132],[834,1135],[842,1133],[848,1136],[853,1133],[856,1134],[863,1128],[892,1127],[897,1131],[900,1129],[908,1133],[919,1132],[929,1134],[933,1130],[944,1129]]],"bb":[781,1127,944,1164],"cx":862,"cy":1145},{"id":"route-208","name":"Route 208","t":"r","g":"route","kind":"route","nick":"The Meadow Road","sum":"After the cold stone of the southern tunnel on Route 207, Route 208 opens into a river valley of meadows and berry patches with Hearthome's skyline in the distance. It is the first place travelers feel warmth in a day.","facts":[["Connects","Route 207 (southern Coronet tunnel from Oreburgh City) ↔ Hearthome City"],["Travel time","2 days on foot"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Junction Ranger Hut, where Route 208 meets the Route 207 tunnel"]],"segs":[[[944,1129],[947,1127],[965,1140],[972,1142],[983,1139],[992,1132],[1003,1131],[1007,1136],[1018,1140],[1049,1138],[1068,1128],[1104,1129],[1109,1127],[1118,1134],[1128,1134],[1136,1127],[1136,1118],[1132,1112]]],"bb":[944,1112,1136,1142],"cx":1040,"cy":1127},{"id":"route-209","name":"Route 209","t":"r","g":"route","kind":"route","nick":"The Quiet Road","sum":"Open country, rolling hills and low stone walls, with a very old place at its center: the Lost Tower, a haunting memorial that locals visit and tourists avoid.","facts":[["Connects","Hearthome City ↔ Solaceon Town"],["Travel time","4–6 days on foot"],["Danger","★★☆☆☆ (★★★☆☆ near the Lost Tower at night)"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Lost Tower Ranger Hut, below the Lost Tower"]],"segs":[[[1132,1112],[1159,1112],[1167,1104],[1173,1091],[1182,1081],[1206,1070],[1216,1059],[1219,1051],[1219,1041],[1216,1038],[1214,1029],[1214,1017],[1220,999],[1219,989],[1215,983],[1222,975]],[[1132,1112],[1126,1107],[1126,1099],[1144,1080],[1144,1068],[1140,1064],[1138,1054],[1145,1047],[1156,1045],[1162,1031]],[[1162,1031],[1170,1026],[1194,1002],[1202,998],[1222,975]]],"bb":[1126,975,1222,1112],"cx":1174,"cy":1043},{"id":"route-210","name":"Route 210","t":"r","g":"route","kind":"route","nick":"The Moor Road","sum":"Wind-swept hills, heather and fog on the mountain's eastern flank. It feels remote, though it is not far from civilization. This is the road pilgrims, scholars and mountain travelers take when they leave Celestic Town.","facts":[["Connects","Celestic Town ↔ Solaceon Town ↔ Route 215 junction"],["Travel time","4 days (Celestic to Solaceon); 2 days (Solaceon to the Route 215 junction)"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger radio at the Café Cabin; the Tunnel Gate post in Celestic covers the north end"]],"segs":[[[1061,769],[1071,772],[1081,770],[1092,772],[1098,779],[1118,771],[1127,782],[1132,783],[1137,788],[1144,802],[1151,809],[1172,816],[1188,827],[1203,830],[1214,840],[1217,851],[1213,856],[1213,867],[1226,883],[1228,899],[1222,912],[1222,924],[1231,935],[1232,940],[1229,962],[1222,969],[1222,975]]],"bb":[1061,769,1232,975],"cx":1146,"cy":872},{"id":"route-211","name":"Route 211","t":"r","g":"route","kind":"route","nick":"The Mountain Road","sum":"A steady climb out of Eterna's greenery into bare rock, scree and wind. It marks the end of the \"gentle\" part of Sinnoh. Here the mountain starts to dictate the pace.","facts":[["Connects","Eterna City ↔ Mt. Coronet Pass ↔ Celestic Town"],["Travel time","2 days on foot through Mt. Coronet Pass; the Coronet Spine from the Crossing to Southgate takes 16–20 days"],["Danger","★★★☆☆"],["Clearance","Pathfinder (2+ badges), or a hired guide. The Spine section past the Crossing Post needs Warden (5+ badges) and a Ranger permit; Pathfinders may cross it with a Greenstation guide"],["Ranger station","Cairn Station Ranger Post (shelter, weather board); Tunnel Gate post at Celestic"]],"segs":[[[793,755],[806,756],[811,754],[821,756],[831,767],[840,767],[845,763],[885,761],[889,764],[897,764],[908,761],[922,771],[934,771],[939,767],[943,768],[962,763],[974,778],[995,776],[997,771],[1017,774],[1020,771],[1024,772],[1029,767],[1056,764],[1061,769]],[[953,598],[956,604],[947,618],[942,638],[954,652],[958,651],[963,659],[963,666],[957,668],[955,677],[958,685],[965,692],[964,703],[970,725],[969,729],[978,743],[976,754],[980,776],[966,780],[967,784],[963,794],[966,812],[963,819],[956,824],[952,833],[965,861],[975,870],[985,888],[985,906],[975,933],[982,937],[982,942],[986,944],[983,971],[992,982],[988,994],[980,1000],[980,1005],[976,1009],[975,1029],[980,1035],[969,1048],[966,1056],[961,1058],[957,1071],[957,1086],[947,1097],[941,1111],[944,1129]]],"bb":[793,598,1061,1129],"cx":927,"cy":863},{"id":"route-212","name":"Route 212","t":"r","g":"route","kind":"route","nick":"The Reed Road","sum":"South of Hearthome the farmland dissolves into drainage country: reed beds, braided creeks, old dikes and raised log causeways. The ground is never quite solid and never quite water. Two boundaries press on the road: the Safari Zone's tall perimeter wall to the east, and the Grand Marsh's open boardwalk edge to the west.","facts":[["Connects","Hearthome City ↔ Pastoria City"],["Travel time","12–16 days on foot (about 10 days by the paved Route 240 and Route 242 detour through Majolica Town)"],["Danger","★★★☆☆"],["Clearance","Pathfinder (2+ badges), or a research permit, or a licensed Wetlands Trust guide"],["Ranger station","Ranger desk at Heron Post (Route House); Wetlands Trust wardens on the boardwalks"]],"segs":[[[1132,1112],[1132,1130],[1146,1145],[1144,1164],[1152,1178],[1154,1193],[1144,1205],[1143,1222],[1139,1235],[1119,1256],[1112,1267],[1110,1285],[1118,1293],[1128,1298],[1141,1311],[1144,1319],[1146,1342],[1170,1363],[1174,1371],[1188,1383],[1218,1395],[1225,1390],[1231,1390],[1235,1385],[1280,1388],[1285,1384]]],"bb":[1110,1112,1285,1395],"cx":1197,"cy":1253},{"id":"route-213","name":"Route 213","t":"r","g":"route","kind":"route","nick":"The Sea Road","sum":"A paved coastal highway of delta flats, red sea cliffs, humming dunes and long empty beaches, always with the East Sea on the right-hand side. It is the most beautiful road in the south and the easiest to underestimate: the sea is close, the storms are sudden, and the cliffs are softer than they look.","facts":[["Connects","Pastoria City ↔ Neighborly Town"],["Travel time","8 days on foot (4 by bike or coastal bus)"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Cape Gannet Light (Route House)"]],"segs":[[[1285,1384],[1283,1380],[1302,1365],[1329,1337],[1340,1331],[1359,1329],[1396,1292],[1444,1279],[1466,1264],[1482,1257],[1523,1249],[1530,1243],[1530,1238],[1538,1230],[1541,1230]]],"bb":[1283,1230,1541,1384],"cx":1412,"cy":1307},{"id":"route-214","name":"Route 214","t":"r","g":"route","kind":"route","nick":"The Gold Road","sum":"Locals call it that because every second vehicle has a sponsor's name on the door. Eastern Sinnoh's main artery: freight trucks, Contest coaches, commuter buses, cyclists in team colors, Gym challengers with sore knees and, in the summer, a steady line of Coordinators heading for the Grand Festival.","facts":[["Connects","Veilstone City ↔ Crown City (by the Crown Spur) ↔ Valor Lakefront and Grand Festival ↔ Neighborly Town"],["Travel time","6 days on foot Veilstone to Crown City; 12 days Veilstone to Neighborly by the Lake Road (about half that by bicycle or bus)"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Windbreak House (Route House)"]],"segs":[[[1510,858],[1509,866],[1530,882],[1547,883],[1552,880],[1562,879],[1567,884],[1568,921],[1565,924],[1565,930],[1548,951],[1548,984],[1566,1007],[1579,1006],[1584,1011]],[[1584,1011],[1579,1006],[1566,1007],[1562,998],[1551,987],[1546,987],[1536,999],[1534,1005],[1533,1043],[1522,1061],[1522,1091],[1534,1113],[1534,1137],[1523,1157],[1522,1164],[1526,1169],[1522,1182],[1528,1187],[1526,1193],[1528,1195],[1527,1212],[1530,1226],[1541,1230]]],"bb":[1509,858,1584,1230],"cx":1546,"cy":1044},{"id":"route-215","name":"Route 215","t":"r","g":"route","kind":"route","nick":"The Highland Road","sum":"A long, rain-prone highland trail that climbs out of the Solaceon valley and descends toward Veilstone's cliffs. Wind farms appear first as flickering lights on the horizon and later as a forest of slow white blades.","facts":[["Connects","Route 210 junction (near Solaceon Town) ↔ Veilstone City"],["Travel time","8 days on foot"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Gale Post (Route House, radio)"]],"segs":[[[1225,928],[1234,932],[1269,932],[1281,928],[1309,928],[1329,919],[1336,919],[1348,928],[1356,928],[1371,917],[1393,914],[1417,889],[1431,882],[1456,881],[1468,878],[1488,866],[1501,866],[1510,858]]],"bb":[1225,858,1510,932],"cx":1367,"cy":895},{"id":"route-216","name":"Route 216","t":"r","g":"route","kind":"route","nick":"The Back Door","sum":"Where Route 217 crosses the snow country in the open, Route 216 goes into the mountain. A hard climb up a frozen gully ends in a cave mouth, and beyond it lies the North Gallery: a lit, roped, ice-glazed tunnel that runs for days toward the heart of Mt. Coronet.","facts":[["Connects","Greenstation Town ↔ the north junction of the Route 211 spine (Mt. Coronet)"],["Travel time","6–8 days on foot"],["Danger","★★★★☆"],["Clearance","Warden (5+ badges), plus a Ranger permit past the Crossing. Pathfinders (2+) may go with a Greenstation guide"],["Ranger station","The Crossing Post (permit desk) and the Portal House (Ranger Tilda Brook)"]],"segs":[[[847,432],[858,443],[860,462],[889,505],[889,529],[887,534],[893,559],[890,565],[896,576],[904,583],[915,588],[945,589],[953,598]]],"bb":[847,432,953,598],"cx":900,"cy":515},{"id":"route-217","name":"Route 217","t":"r","g":"route","kind":"route","nick":"The Long White Road","sum":"Route 217 is the north's answer to anyone who thinks Sinnoh is a chain of neighboring towns. For a week there is no town: only red marker poles, wind, a frozen lake that groans at night, and one lodge.","facts":[["Connects","Greenstation Town ↔ Acuity Lakefront ↔ Snowpoint City"],["Travel time","12–16 days on foot in settled weather; 20+ if a storm cycle pins you"],["Danger","★★★★★"],["Clearance","Vanguard (7+ badges). Wardens (5+) may go with a Greenstation guide, or on a research permit as far as the Acuity Lakefront station"],["Ranger station","Stillwater Hut (Route House warden, radio); Acuity Lakefront Ranger post"]],"segs":[[[847,432],[835,439],[811,414],[809,370],[812,304],[807,291],[806,274],[817,268],[833,269],[836,266],[834,250],[837,247],[837,232],[843,226],[859,221],[871,215],[877,209],[893,209],[901,201],[901,195],[893,190]]],"bb":[806,190,901,439],"cx":853,"cy":314},{"id":"route-218","name":"Route 218","t":"r","g":"route","kind":"route","nick":"The Western Road","sum":"Sinnoh's busiest freight corridor outside Jubilife: steel, canned fish, lumber and ship's stores roll east, and passengers, machinery and Pokémon-care goods roll west. The road is fully paved, well lit at junctions and shared by trucks, coaches, cyclists and the occasional walker.","facts":[["Connects","Jubilife City ↔ Canalave City"],["Travel time","6–8 days on foot; about 4 by bicycle; the Canalave Coach (bus) takes two long days"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Westbank Waystation (Route House, radio)"]],"segs":[[[552,1151],[544,1151],[537,1157],[507,1158],[488,1168],[474,1170],[454,1177],[434,1175],[419,1168],[411,1160],[409,1142],[415,1127],[412,1120],[362,1120],[350,1110],[348,1090],[343,1085],[333,1082],[325,1074],[331,1067],[329,1051]]],"bb":[325,1051,552,1177],"cx":438,"cy":1114},{"id":"route-219","name":"Route 219","t":"r","g":"route","kind":"route","nick":"The Port Road","sum":"A short, flat, busy road of salt air and trucks, running through tidal flats and market gardens to the water. Almost everything that enters or leaves Sandgem by sea passes along it, and about once a week something comes down it that nobody has seen before.","facts":[["Connects","Sandgem Town ↔ Sandgem Port"],["Travel time","2 days on foot; 1 day by bicycle"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Port Road Ranger Kiosk, at the Sandgem Port gate"]],"segs":[[[557,1335],[564,1339],[568,1346],[567,1353],[558,1360],[559,1380]]],"bb":[557,1335,568,1380],"cx":562,"cy":1357},{"id":"route-220","name":"Route 220","t":"r","g":"route","kind":"route","nick":"The Long Coast Road","sum":"Sinnoh's longest unbroken seaside walk: cliffs, dunes, salt pans and fishing hamlets strung along a paved road that never quite leaves earshot of the sea. Slower than it looks. The road is paved and safe, but the villages are far apart and the weather is rarely on your side.","facts":[["Connects","Sandgem Port ↔ Sage Town"],["Travel time","10–12 days on foot; about 6 by bicycle"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Driftwood Rest (Route House)"]],"segs":[[[559,1380],[558,1359],[563,1356],[570,1356],[603,1383],[614,1389],[614,1393],[626,1394],[632,1399],[654,1402],[670,1414],[725,1467],[739,1476],[757,1483],[789,1513],[853,1550],[879,1571],[914,1587],[917,1585],[925,1585],[929,1588],[934,1586],[944,1595],[945,1602],[949,1604],[951,1610],[968,1617],[1002,1651],[1042,1674],[1057,1673]]],"bb":[558,1356,1057,1674],"cx":807,"cy":1515},{"id":"route-221","name":"Route 221","t":"r","g":"route","kind":"route","nick":"The Freight Road","sum":"This is Sinnoh's busiest trucking corridor outside Jubilife: container trucks, refrigerated vans, buses, couriers and the odd lost tourist. The road crosses the Grand Marsh's delta on a long causeway, then runs for days along cliffs and estuaries toward the cranes of the southern port.","facts":[["Connects","Pastoria City ↔ South Sinnoh Port"],["Travel time","10 days on foot (4–6 by bike or bus; trucks do it in 2 days)"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Salt Pan Rest (Route House)"]],"segs":[[[1285,1384],[1281,1381],[1272,1382],[1263,1395],[1240,1399],[1216,1399],[1182,1438],[1168,1445],[1154,1448],[1141,1460],[1139,1471],[1153,1482],[1159,1483],[1170,1494],[1176,1504],[1176,1514],[1142,1545],[1114,1593],[1104,1604],[1094,1636],[1057,1673]]],"bb":[1057,1381,1285,1673],"cx":1171,"cy":1527},{"id":"route-222","name":"Route 222","t":"r","g":"route","kind":"route","nick":"The Sunrise Road","sum":"It runs along the south coast where the land flattens into tide flats, salt pans, dunes and low wind-bent scrub, and because it points east, travelers walk toward the dawn for much of every morning. Locals measure distances in tides, not hours: \"two tides to Daybreak\" is the Neighborly way of saying a day and a half.","facts":[["Connects","Neighborly Town ↔ the Sunrise Fork ↔ Daybreak Town and Camellia Town (with a paved link on from Camellia to Sunyshore City)"],["Travel time","6 days on foot Neighborly to the Sunrise Fork; 1 day on to Daybreak or Camellia; 2 more days from Camellia to Sunyshore (about half that by bicycle)"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Salt Gate House (Route House)"]],"segs":[[[1541,1230],[1548,1228],[1558,1237],[1568,1230],[1628,1229],[1643,1226],[1645,1234],[1645,1226],[1656,1223],[1672,1223],[1681,1225],[1684,1228],[1699,1230],[1730,1228],[1741,1240],[1743,1248],[1758,1248],[1761,1251],[1761,1261],[1763,1263]],[[1644,1234],[1646,1225],[1656,1223],[1672,1223],[1681,1225],[1684,1228],[1699,1230],[1722,1230],[1730,1222],[1732,1207],[1743,1197],[1742,1190],[1745,1187],[1767,1187],[1779,1176],[1788,1180],[1796,1179],[1801,1174],[1803,1166]]],"bb":[1541,1166,1803,1263],"cx":1672,"cy":1214},{"id":"route-224","name":"Route 224","t":"r","g":"route","kind":"route","nick":"The Green Road","sum":"It is the spine of the eastern peninsula, running through a belt of orchards, millstreams and the wooded ridge locals call the Brusselwood. Greenhouses glow on the ridgetop at night, timber trucks rumble through the forest margin, and anyone heading for a Contest in Arrowroot, Brussel or Neighborly eventually travels it.","facts":[["Connects","Arrowroot Town ↔ Brussel Town ↔ Neighborly Town (meeting Route 214 and Route 213 at the Neighborly junction)"],["Travel time","6 days on foot end to end (2–4 days Arrowroot to Brussel, 2–4 days Brussel to Neighborly); about 2–4 days by bicycle"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Timber Stop (Route House)"]],"segs":[[[1633,1107],[1640,1105],[1644,1115],[1644,1124],[1639,1130],[1637,1159],[1621,1173],[1614,1173],[1602,1163],[1596,1165],[1589,1173],[1587,1182],[1566,1198],[1550,1214],[1549,1226],[1541,1230]]],"bb":[1541,1105,1644,1230],"cx":1592,"cy":1167},{"id":"route-225","name":"Route 225","t":"r","g":"route","kind":"route","nick":"The Feeder Road","sum":"Named for the pylons that carry Sunyshore's solar power to Crown City, which march beside it the whole way. Cable, coastline and sunlight define the route: white cliffs and gull-colored sea in the first half, wide shore and glittering panels in the second.","facts":[["Connects","Crown City ↔ Arrowroot Town ↔ Sunyshore City"],["Travel time","8 days on foot end to end (Crown to Arrowroot 2–4 days, Arrowroot to Sunyshore 4 days); about 4 by bicycle"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Pylon Nine Station (Route House)"]],"segs":[[[1584,1011],[1587,1020],[1582,1029],[1583,1036],[1603,1061],[1616,1085],[1625,1094],[1625,1099],[1633,1107],[1648,1104],[1655,1112],[1656,1130],[1660,1134],[1668,1137],[1742,1136],[1752,1145],[1752,1151],[1758,1157],[1772,1158],[1777,1164],[1777,1173],[1788,1180],[1796,1179],[1801,1174],[1803,1166]]],"bb":[1582,1011,1803,1180],"cx":1692,"cy":1095},{"id":"route-226","name":"Route 226","t":"r","g":"route","kind":"route","nick":"The Long Road","sum":"An ordinary highway that happens to cross four climates in ten days. It leaves Snowpoint through steam and geothermal-heated pavement, descends past Lilypad's hot springs, crosses the Thaw Line where the snow finally stops, and ends in wind and salt spray on the cliffs above Veilstone.","facts":[["Connects","Snowpoint City ↔ Lilypad Town ↔ Lucario Kingdom ↔ Veilstone City"],["Travel time","18–22 days on foot end to end; 8–12 by bicycle or mount; about 6 by long-haul coach when the road is plowed"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Thaw Line Station (Route House); the Kingdom Gate Post (Ranger hut)"]],"segs":[[[893,190],[900,194],[901,201],[900,208],[891,217],[891,230],[913,253],[927,272],[934,295],[944,307],[947,321],[951,325],[959,326],[966,336],[966,360],[975,380],[979,384],[981,414],[1008,467],[1016,488],[1025,497],[1043,508],[1063,529],[1080,560],[1084,575],[1102,592],[1119,598],[1131,610],[1141,634],[1141,641],[1145,641],[1158,650],[1162,649],[1171,658],[1175,657],[1188,668],[1201,674],[1222,695],[1232,708],[1242,736],[1267,777],[1296,803],[1313,808],[1329,808],[1353,797],[1370,797],[1395,824],[1426,828],[1453,851],[1478,856],[1492,871],[1505,870],[1509,866],[1510,858]]],"bb":[891,190,1510,871],"cx":1200,"cy":530},{"id":"route-227","name":"Route 227","t":"r","g":"route","kind":"route","nick":"The Warm Gallery","sum":"In a country defined by cold, Route 227 is a rare place that is warm. The tunnel was bored for the narrow-gauge Lilypad Line, a freight railway that once carried ore and now carries passengers, mail, geothermal pipe and frozen fish. Heat from the mountain's hot springs runs through the rock, so the middle of the tunnel is damp, foggy and mild, with ferns growing near the lamps.","facts":[["Connects","Greenstation Town ↔ Lilypad Town"],["Travel time","4 days on foot (overnights at the Steam Halt); about 10 hours by the Lilypad Line train"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at the Steam Halt (signal station and bunkhouse)"]],"segs":[[[847,432],[886,433],[907,413],[916,394],[916,387],[930,372],[931,361],[949,344],[950,329],[955,325],[960,328]]],"bb":[847,325,960,433],"cx":903,"cy":379},{"id":"route-228","name":"Route 228","t":"r","g":"route","kind":"route","nick":"The Rope Road","sum":"Route 228 is paved, short and ordinary on a clear day. In a storm it becomes the reason Shelter Town exists. A guide-rope runs the whole length of the road, threaded through numbered bell posts every two hundred paces, each with a brass bell. When the snow comes in sideways, travelers hold the rope, ring the nearest bell, and walk toward the sound of the next.","facts":[["Connects","Shelter Town ↔ Greenstation Town"],["Travel time","2–4 days on foot (two long days with early starts; most parties take four)"],["Danger","★★☆☆☆ (★★★★☆ in a blizzard)"],["Clearance","Open. While a blizzard warning is posted: Warden (5+ badges), or a Greenstation guide"],["Ranger station","Bell-post rope line, run by the Northern District Ranger Station in Greenstation"]],"segs":[[[801,490],[808,459],[816,452],[825,455],[836,454],[837,448],[846,438],[847,432]]],"bb":[801,432,847,490],"cx":824,"cy":461},{"id":"route-229","name":"Route 229","t":"r","g":"route","kind":"route","nick":"The Snow Line Road","sum":"On Route 229 you can walk from autumn into winter in an afternoon. The road leaves Sandalstraw's orchards and farms, climbs to the grey foothills, ducks into the Foothill Cut, a long tunnel through the ridge, and emerges on the other side into snow.","facts":[["Connects","Sandalstraw Town ↔ Shelter Town"],["Travel time","4 days on foot"],["Danger","★☆☆☆☆ (★★★☆☆ once the snow closes in)"],["Clearance","Open. Once the snow closes in: Pathfinder (2+ badges), or a hired guide"],["Ranger station","Ranger desk at the Halfway House (Route House)"]],"segs":[[[719,575],[729,587],[743,587],[767,564],[795,530],[796,518],[803,511],[801,490]]],"bb":[719,490,803,587],"cx":761,"cy":538},{"id":"route-230","name":"Route 230","t":"r","g":"route","kind":"route","nick":"The Timber Road","sum":"Eterna's beams, barrels and charcoal come down this road, and Sandalstraw's straw goods go with them. The countryside is working woodland: larch and pine plantations in rows, sawmills on the river, charcoal clamps in clearings, and logging roads that climb into the hills on either side. It is not wilderness, and its Pokémon have adapted to saws and lorries with the cheerful pragmatism of a population that has lived beside industry for generations.","facts":[["Connects","Sandalstraw Town ↔ Eterna City"],["Travel time","4 days on foot; two days by coach"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","North Gate Ranger Post (vine-mat warnings)"]],"segs":[[[719,575],[724,581],[724,595],[721,598],[720,663],[749,689],[749,698],[741,707],[741,715],[744,718],[753,718],[755,716],[762,726],[767,726],[790,746],[790,752],[793,755]]],"bb":[719,575,793,755],"cx":756,"cy":665},{"id":"route-231","name":"Route 231","t":"r","g":"route","kind":"route","nick":"The Heathway","sum":"This is where the ring road leaves the coast and the country gets large. The pavement crosses salt meadow, high heath, a reedy lake and a long run of hay and straw land, with no shelter except two Route Houses and the occasional herdsman's hut. Wind is constant. Sheep are everywhere.","facts":[["Connects","Squallville ↔ Sandalstraw Town"],["Travel time","6 days on foot; four by coach or bicycle"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Heath Gate (Route House)"]],"segs":[[[561,762],[564,753],[588,730],[603,729],[608,732],[616,732],[622,726],[637,695],[644,688],[644,682],[652,663],[681,636],[689,610],[701,597],[704,576],[714,571],[719,575]]],"bb":[561,571,719,762],"cx":640,"cy":666},{"id":"route-232","name":"Route 232","t":"r","g":"route","kind":"route","nick":"The Salt Road","sum":"Where Route 233 smells of honey and cocoa, Route 232 smells of kelp, tar and cold iron. It runs along the Long Strand and over the dune ridge, past salt pans and sea stacks, to the tidal causeway into Squallville. The wind arrives from the west with nothing between it and the horizon, and everyone on the road checks the sky as a habit.","facts":[["Connects","Chocovine Town ↔ Squallville"],["Travel time","4–6 days on foot; two long days by coach in fair weather"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Stormglass Post (Route House)"]],"segs":[[[457,891],[459,884],[464,883],[471,876],[479,862],[524,822],[530,811],[536,790],[561,762]]],"bb":[457,762,561,891],"cx":509,"cy":826},{"id":"route-233","name":"Route 233","t":"r","g":"route","kind":"route","nick":"The Sweet Road","sum":"Honey wagons and cut-flower trucks roll one way; cocoa lorries and tins of confectionery roll the other. Coach drivers announce it as the Sweet Road at every stop, and hauliers will tell you it is the only road in Sinnoh with a smell timetable: lavender and clover near Floaroma, warm blossom through the orchards, and then, long before any chimney is visible, the dark roasted smell of Chocovine coming down the terraces on a south wind.","facts":[["Connects","Floaroma Town ↔ the Ring Junction (meeting Route 234 from Canalave City) ↔ Chocovine Town"],["Travel time","4 days on foot; two long days by coach or bicycle"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Orchard Mile Ranger Hut, by the berry-grading shed"]],"segs":[[[558,980],[542,994],[522,1001],[511,1008],[497,1011],[483,986],[475,960],[458,938],[457,916],[447,903],[447,898],[454,891],[457,891]]],"bb":[447,891,558,1011],"cx":502,"cy":951},{"id":"route-234","name":"Route 234","t":"r","g":"route","kind":"route","nick":"The Orchard Road","sum":"A gently rolling coastal plain of berry orchards, hedgerows and wind-bent poplars, with the sea visible on the left for the first half-day. This is the route Canalave's fishermen and shipwrights use to reach Floaroma's markets, and the route Floaroma's flower growers use to ship cut flowers to the port.","facts":[["Connects","the Route 218 fork (east of Canalave) ↔ the Route 233 ring-road junction near Floaroma Town"],["Travel time","4 days on foot; 2 by bicycle (about 6 from Canalave itself)"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Berry Row Ranger Hut, at the ring-road junction"]],"segs":[[[412,1120],[415,1112],[438,1089],[451,1083],[456,1078],[459,1070],[481,1047],[485,1035],[491,1029],[492,1017],[497,1011]]],"bb":[412,1011,497,1120],"cx":454,"cy":1065},{"id":"route-235","name":"Route 235","t":"r","g":"route","kind":"route","nick":"The Hairpin Road","sum":"A paved mining road from an older age, once the only way to haul ore down to Jubilife, now kept open by Alamos's cheesemakers, Oreburgh's courier guild and a stubborn preservation society. It climbs more than it needs to, because the engineers who laid it were routing around two long-vanished quarries.","facts":[["Connects","Jubilife City (north-east outskirts) ↔ Alamos Town spur ↔ Oreburgh City (north gate)"],["Travel time","8 days on foot; about 4 by bicycle"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Cheesewright's Rest (Route House)"]],"segs":[[[552,1151],[559,1149],[572,1138],[588,1133],[601,1120],[601,1104],[597,1096],[597,1085],[602,1079],[609,1079],[613,1087],[622,1096],[640,1101],[657,1114],[672,1116],[677,1111],[682,1118],[703,1131],[729,1131],[745,1147],[762,1147],[781,1164]]],"bb":[552,1079,781,1164],"cx":666,"cy":1121},{"id":"route-236","name":"Route 236","t":"r","g":"route","kind":"route","nick":"The Coach Road","sum":"For most of Sinnoh's civilians, this is the way to Oreburgh: paved, signed and scheduled. Coaches leave Jubilife's south terminal hourly. Ore haulers, schoolchildren and business travelers ride the same road as walkers, and the trainers who take it are usually the ones who got a refund on the Route 203 tunnel.","facts":[["Connects","Jubilife City ↔ Oreburgh City, joining Route 237 for the last stretch"],["Travel time","6–8 days on foot; about 2 days by bicycle; the coach takes twelve hours"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Dustman's Rest (Route House)"]],"segs":[[[552,1151],[559,1154],[562,1166],[561,1172],[572,1183],[572,1190],[609,1219],[628,1222],[679,1221],[687,1225],[710,1248],[740,1248],[751,1244],[765,1229],[767,1216],[772,1208],[774,1191],[790,1175],[788,1167],[781,1164]]],"bb":[552,1151,790,1248],"cx":671,"cy":1199},{"id":"route-237","name":"Route 237","t":"r","g":"route","kind":"route","nick":"The Ore Road","sum":"Oreburgh's coal and ore leave the city by this route for Sandgem Port, so the road is built for weight: broad lanes, deep gravel shoulders, weighbridges and truck stops with wash bays for Pokémon. It is the working spine of the southwest, and nobody who lives on it ever calls it quiet.","facts":[["Connects","Sandgem Town ↔ Oreburgh City, joining Route 236 for the last stretch"],["Travel time","6–8 days on foot; about 3 days by bicycle; ore trucks do it in two long days"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ore Road Ranger Post, at the Oreburgh truck stop"]],"segs":[[[557,1335],[569,1339],[580,1338],[594,1327],[605,1323],[627,1301],[632,1301],[638,1297],[664,1271],[678,1262],[690,1258],[702,1258],[710,1248],[740,1248],[751,1244],[765,1229],[767,1216],[772,1208],[774,1191],[790,1175],[788,1167],[781,1164]]],"bb":[557,1164,790,1339],"cx":673,"cy":1251},{"id":"route-238","name":"Route 238","t":"r","g":"route","kind":"route","nick":"The Woodcutters' Way","sum":"A rough track through drover's lanes, then a long wooded stretch under the broad oaks of Bewilder Forest, then out into hedged pasture on Sandgem's doorstep. Slower than Route 202, wilder, and the one where it is easiest to get lost.","facts":[["Connects","Jubilife City (south edge, near Route 202) ↔ Bewilder Forest ↔ Sandgem Town (north edge)"],["Travel time","6–8 days on foot"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Woodcutters' Ranger Hut, at the Bewilder Forest edge"]],"segs":[[[552,1151],[564,1163],[570,1164],[568,1207],[573,1220],[570,1246],[574,1250],[573,1270],[565,1285],[563,1304],[568,1317],[568,1328],[561,1335],[557,1335]]],"bb":[552,1151,574,1335],"cx":563,"cy":1243},{"id":"route-239","name":"Route 239","t":"r","g":"route","kind":"route","nick":"The Meltwater Road","sum":"Route 239 climbs out of Solaceon's sheltered valley into the foothills on the east face of Mt. Coronet, following a cold, milk-pale stream that begins as glacier melt on the white plateau above. It is the only way to Michina Town, and nearly everyone on it is going for one of four reasons: wool, stone, scholarship, or a question they hope the Ruins will answer.","facts":[["Connects","Solaceon Town ↔ Michina Town (with the Pilgrims' Spur on to Michina Ruins)"],["Travel time","4–6 days on foot"],["Danger","★★☆☆☆ (★★★☆☆ in spring melt, or above the Cairn Gallery after dark)"],["Clearance","Open. During spring melt: Pathfinder (2+ badges), or a hired guide"],["Ranger station","Ranger desk at Terrace Rest (Route House)"]],"segs":[[[1222,975],[1209,982],[1182,979],[1175,976],[1153,954],[1144,949],[1137,949],[1128,941]]],"bb":[1128,941,1222,982],"cx":1175,"cy":961},{"id":"route-240","name":"Route 240","t":"r","g":"route","kind":"route","nick":"The Potters' Road","sum":"A broad paved highway across gentle plain, busy with clay carts, couriers and the Kiln Line bus. Every mile is marked by a hand-glazed mile tile, and no two are alike. Locals can tell a stranger by whether they look at the tiles.","facts":[["Connects","Hearthome City ↔ Majolica Town"],["Travel time","4 days on foot (two long days by bike or the Kiln Line bus)"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Tilework Station (Route House)"]],"segs":[[[1132,1112],[1136,1123],[1147,1132],[1158,1135],[1183,1152],[1204,1159],[1214,1153],[1220,1153],[1223,1156]]],"bb":[1132,1112,1223,1159],"cx":1177,"cy":1135},{"id":"route-241","name":"Route 241","t":"r","g":"route","kind":"route","nick":"The Millpond Road","sum":"A paved road over low rolling country of mill ponds, hill orchards and chalk cuttings. Windpumps turn in every field. It is the pleasant way to leave the clay country: wide verges, cider stalls, and a sense that nobody is in a hurry.","facts":[["Connects","Majolica Town (via the Route 242 junction) ↔ Route 213 at Three Gulls Crossing"],["Travel time","4–6 days on foot (two long days by bike)"],["Danger","★☆☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Wheelhouse (Route House)"]],"segs":[[[1223,1156],[1228,1166],[1228,1178],[1246,1194],[1254,1197],[1259,1202],[1273,1202],[1307,1211],[1324,1220],[1328,1224],[1330,1232],[1331,1252],[1379,1300]]],"bb":[1223,1156,1379,1300],"cx":1301,"cy":1228},{"id":"route-242","name":"Route 242","t":"r","g":"route","kind":"route","nick":"The Gate Road","sum":"The fast, safe way into Pastoria: a paved highway across farmland, then wet pasture, then reed wall and delta. It is the road the Safari Zone's buses take, so it carries more tourists than any road in the south.","facts":[["Connects","Majolica Town ↔ Pastoria City"],["Travel time","6 days on foot (four by bike or the Gate Line bus)"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Greenbrook Crossing (Route House, radio)"]],"segs":[[[1223,1156],[1228,1166],[1228,1182],[1236,1192],[1244,1212],[1248,1239],[1252,1243],[1269,1243],[1258,1243],[1253,1249],[1253,1278],[1261,1318],[1264,1321],[1265,1363],[1285,1384]]],"bb":[1223,1156,1285,1384],"cx":1254,"cy":1270},{"id":"battle-resort-route-225","name":"Battle Resort Route 225","t":"r","g":"route","kind":"route","nick":"The Training Road","sum":"Everyone on this road is walking toward a test. At the south end is the Fight Area, where trainers learn to win; at the north end is the Survival Area, where they learn to endure; the Resort's \"Full Circuit\" program sells the road between them as the part where the two lessons meet.","facts":[["Connects","Battle Resort Fight Area ↔ Battle Resort Survival Area"],["Travel time","8–10 days on foot (about half that with bikes or mounts, which the Training Pass discourages)"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger radio at Ferndrop Station (Route House)"]],"segs":[[[1325,600],[1322,594],[1321,570],[1334,555],[1330,528],[1339,517],[1335,478],[1342,469],[1354,465],[1364,455],[1368,445],[1368,430],[1378,411],[1379,404],[1383,400],[1386,383]]],"bb":[1321,383,1386,600],"cx":1353,"cy":491},{"id":"battle-resort-route-226","name":"Battle Resort Route 226","t":"r","g":"route","kind":"route","nick":"The Bay Road","sum":"A route of crossings. Where Stark's meltwater meets the tide of the Inner Sound, the north shore becomes salt meadow, mudflat, reed bank and braided river, and the trail is a patient sequence of causeways, fords and rope-lines. It is quiet compared to Battle Resort Route 225: fewer cadets, more herons, long horizons, and fog that turns the Bay into a pale wall.","facts":[["Connects","Battle Resort Survival Area ↔ Stark Fork (the three-way junction with Battle Resort Route 227 and Battle Resort Route 228)"],["Travel time","6–8 days on foot"],["Danger","★★★☆☆"],["Clearance","Pathfinder (2+ badges), or a Survival Area instructor as guide"],["Ranger station","Ford House (Route House and rope-line crew)"]],"segs":[[[1386,383],[1385,380],[1390,370],[1400,361],[1438,361],[1447,368],[1462,370],[1471,365],[1478,365],[1488,373],[1500,373],[1513,367]]],"bb":[1385,361,1513,383],"cx":1449,"cy":372},{"id":"battle-resort-route-227","name":"Battle Resort Route 227","t":"r","g":"route","kind":"route","nick":"The Ash Road","sum":"The only way up Mt. Stark on foot. Heather moor gives way to wind-bent pine, then to black cinder, steam and sulfur-yellow rock. The League's volcano watch keeps the road open, marked, and monitored; it does not keep it safe.","facts":[["Connects","Stark Fork (junction with Battle Resort Route 226 and Battle Resort Route 228) ↔ Mt. Stark"],["Travel time","4–6 days up, 2–4 days down"],["Danger","★★★★☆"],["Clearance","Vanguard (7+ badges). Wardens (5+) may go with a volcano-watch escort or on a research permit"],["Ranger station","Cinder Hut (Route House); volcano-watch station on the rim"]],"segs":[[[1513,367],[1513,355],[1520,350],[1529,349],[1534,342],[1528,326],[1537,316],[1535,287]]],"bb":[1513,287,1537,367],"cx":1525,"cy":327},{"id":"battle-resort-route-228","name":"Battle Resort Route 228","t":"r","g":"route","kind":"route","nick":"The Spine","sum":"The east arm's ridge is a country of waterfalls, terraced orchards, and warm caves, and it is the island's quiet side. The Resort's glossy edge never quite reaches it. The people here are the Terrace families: the island's original farmers, who grow the berries, honey and fruit the Resort restaurants advertise as \"island-grown\" and who regard the advertising with a mixture of pride and suspicion.","facts":[["Connects","Stark Fork (junction with Battle Resort Route 226 and Battle Resort Route 227) ↔ Battle Resort Port"],["Travel time","10–12 days on foot (the island's longest route)"],["Danger","★★★☆☆"],["Clearance","Pathfinder (2+ badges), or a Survival Area instructor as guide"],["Ranger station","Ranger desk at Overlook Post (Route House)"]],"segs":[[[1513,367],[1529,371],[1555,372],[1566,383],[1572,394],[1575,413],[1596,433],[1596,451],[1605,463],[1603,487],[1606,492],[1606,512],[1603,517],[1603,527],[1613,544],[1613,558],[1609,570],[1611,597],[1601,609]]],"bb":[1513,367,1613,609],"cx":1563,"cy":488},{"id":"battle-resort-route-229","name":"Battle Resort Route 229","t":"r","g":"route","kind":"route","nick":"The Shell Road","sum":"The island's gentle end: dunes, tide pools, grassy headlands, and a long beach where the Resort's villas look down on the water. It feels like a holiday. Trainers who have just walked the Spine arrive tanned and blistered and feel a bit ridiculous, and the Resort is perfectly happy to sell them a spa towel.","facts":[["Connects","Battle Resort Port ↔ Resort Area"],["Travel time","4 days on foot (the Resort's sea shuttle still takes an hour)"],["Danger","★★☆☆☆"],["Clearance","Open: Trailhand (0+ badges)"],["Ranger station","Ranger desk at Shell Station (Route House)"]],"segs":[[[1601,609],[1612,608],[1619,615],[1623,615],[1629,624],[1649,643],[1664,648],[1678,662]]],"bb":[1601,608,1678,662],"cx":1639,"cy":635},{"id":"pavilion-road","name":"Pavilion Road","t":"r","g":"route","kind":"route","nick":"","sum":"The short natural track from Champion's Port to Elite Four Island, about a day on foot. Challengers walk it with a League escort after ringing the Challenger's Bell at the gate.","facts":[["Connects","Champion's Port ↔ Elite Four Island"],["Travel time","about 2 days on foot"],["Clearance","Eight badges and a Challenge Pass from the Registrar"],["Ranger station","League security posts at the Challenger's Bell gate and the Pavilion"]],"segs":[[[1724,883],[1729,868],[1746,854]]],"bb":[1724,854,1746,883],"cx":1735,"cy":868}];
const PD_BY={};PD.forEach(f=>{PD_BY[f.id]=f;});
const PLACES=PD.map(f=>f.name).sort();

/* ---------- store: refs, local copies, write queue ---------- */
const SET_ALWAYS=new Set(['meta','gl','gn','bn','pl','gp','mg','bt','gb','gt','np','bm','bg','sh','sg','cd']);
function refFor(sc,id){
  const db=S.db;
  switch(sc){
    case 't':return db.collection('trainers').doc(id);
    case 'p':{const i=id.indexOf('/');return db.collection('trainers').doc(id.slice(0,i)).collection('pokemon').doc(id.slice(i+1));}
    case 'ppl':return db.collection('people').doc(id);
    case 'j':return db.collection('journal').doc(id);
    case 'l':return db.collection('leads').doc(id);
    case 'n':return db.doc('data/users/'+S.me.id+'/profile').collection('notes').doc(id);
    case 'meta':return db.collection('meta').doc('table');
    case 'gl':return db.collection('gm').doc('loy_'+id);
    case 'gn':return db.collection('gm').doc('npc_'+id);
    case 'tl':return db.collection('timeline').doc(id);
    case 'pin':return db.collection('pins').doc(id);
    case 'aw':return db.collection('awards').doc(id);
    case 'bn':return db.collection('meta').doc('banner');
    case 'mg':return db.collection('meta').doc('mega');
    case 'bt':return db.collection('meta').doc('battle');
    case 'gb':return db.collection('gm').doc('battle');
    case 'pl':return db.collection('places').doc(id);
    case 'gp':return db.collection('gm').doc('place_'+id);
    case 'gt':return db.collection('gm').doc('nt_'+id);
    case 'np':return db.collection('meta').doc('npcs');
    case 'bm':return db.collection('meta').doc('bmap');
    case 'bg':return db.collection('gm').doc('bmap');
    case 'sh':return db.collection('meta').doc('shops');
    case 'sg':return db.collection('gm').doc('shops');
    case 'cd':return db.collection('meta').doc('conditions');
  }
}
function getLocal(sc,id){
  switch(sc){
    case 't':return S.trainers[id];
    case 'p':{const i=id.indexOf('/');const m=S.pokemon[id.slice(0,i)];return m&&m[id.slice(i+1)];}
    case 'ppl':return S.people[id];
    case 'j':return S.journal[id];
    case 'l':return S.leads[id];
    case 'n':return S.notes[id];
    case 'meta':return S.meta;
    case 'gl':return S.gmLoy[id];
    case 'gn':return S.gmNpc[id];
    case 'tl':return S.timeline[id];
    case 'pin':return S.pins[id];
    case 'aw':return S.awards[id];
    case 'bn':return S.banner;
    case 'mg':return S.megaOk;
    case 'bt':return S.battle;
    case 'gb':return S.battleGm;
    case 'pl':return S.places[id];
    case 'gp':return S.gmPl[id];
    case 'gt':return S.gmNt[id];
    case 'np':return S.npcPub;
    case 'bm':return S.bmap;
    case 'bg':return S.bmGm;
    case 'sh':return S.shopPub;
    case 'sg':return S.shopGm;
    case 'cd':return S.cond;
  }
}
function putLocal(sc,id,d){
  switch(sc){
    case 't':S.trainers[id]=d;break;
    case 'p':{const i=id.indexOf('/');const u=id.slice(0,i);(S.pokemon[u]||(S.pokemon[u]={}))[id.slice(i+1)]=d;break;}
    case 'ppl':S.people[id]=d;break;
    case 'j':S.journal[id]=d;break;
    case 'l':S.leads[id]=d;break;
    case 'n':S.notes[id]=d;break;
    case 'meta':S.meta=d;break;
    case 'gl':S.gmLoy[id]=d;break;
    case 'gn':S.gmNpc[id]=d;break;
    case 'tl':S.timeline[id]=d;break;
    case 'pin':S.pins[id]=d;break;
    case 'aw':S.awards[id]=d;break;
    case 'bn':S.banner=d;break;
    case 'mg':S.megaOk=d;break;
    case 'bt':S.battle=d;break;
    case 'gb':S.battleGm=d;break;
    case 'pl':S.places[id]=d;break;
    case 'gp':S.gmPl[id]=d;break;
    case 'gt':S.gmNt[id]=d;break;
    case 'np':S.npcPub=d;break;
    case 'bm':S.bmap=d;break;
    case 'bg':S.bmGm=d;break;
    case 'sh':S.shopPub=d;break;
    case 'sg':S.shopGm=d;break;
    case 'cd':S.cond=d;break;
  }
}
function dropLocal(sc,id){
  switch(sc){
    case 't':delete S.trainers[id];break;
    case 'p':{const i=id.indexOf('/');const m=S.pokemon[id.slice(0,i)];if(m)delete m[id.slice(i+1)];break;}
    case 'ppl':delete S.people[id];break;
    case 'j':delete S.journal[id];break;
    case 'l':delete S.leads[id];break;
    case 'n':delete S.notes[id];break;
    case 'gl':delete S.gmLoy[id];break;
    case 'gn':delete S.gmNpc[id];break;
    case 'tl':delete S.timeline[id];break;
    case 'pin':delete S.pins[id];break;
    case 'aw':delete S.awards[id];break;
    case 'pl':delete S.places[id];break;
    case 'gp':delete S.gmPl[id];break;
    case 'gt':delete S.gmNt[id];break;
    case 'bg':S.bmGm={};break;
  }
}

const Q=new Map();
function setStatus(kind,msg){
  /* a fresh note stays readable; the plain "Saved" that follows a write waits until it has had its few seconds */
  if(kind==='saved'&&S.noteUntil>Date.now())return;
  S.save=kind==='busy'?{cls:'busy',text:'Saving…'}:kind==='err'?{cls:'err',text:msg||'Could not save'}:kind==='note'?{cls:'',text:msg}:{cls:'',text:'Saved'};
  const el=document.getElementById('savestate');
  if(el){el.className='save '+S.save.cls;el.textContent=S.save.text;}
}
function fail(e){
  const code=(e&&e.code)||'error';
  if(code==='invalid_argument'||code==='permission-denied'){S.ui.writeFail=true;scheduleRender();}
  setStatus('err','Could not save ('+code+')');
}
function save(sc,id,patch,o){
  o=o||{};
  const key=sc+'|'+id;
  let q=Q.get(key);
  if(!q){q={patch:{},inflight:null,timer:0,busy:false,create:false};Q.set(key,q);}
  Object.assign(q.patch,patch);
  if(o.create)q.create=true;
  setStatus('busy');
  clearTimeout(q.timer);
  q.timer=setTimeout(()=>flush(key,sc,id),o.create?0:450);
}
async function flush(key,sc,id){
  const q=Q.get(key);
  if(!q)return;
  if(q.busy){q.timer=setTimeout(()=>flush(key,sc,id),120);return;}
  const patch=q.patch;
  const whole=q.create||SET_ALWAYS.has(sc);
  q.patch={};q.create=false;q.busy=true;q.inflight=patch;
  let err=null;
  try{
    const ref=refFor(sc,id);
    const full=getLocal(sc,id);
    const clean=full?JSON.parse(JSON.stringify(full)):null;
    if(whole){if(clean)await ref.set(clean);}
    else{
      try{await ref.update(patch);}
      catch(e){if(e&&e.code==='invalid_argument'&&clean){await ref.set(clean);}else throw e;}
    }
  }catch(e){err=e;}
  q.busy=false;q.inflight=null;
  if(err){Q.delete(key);fail(err);return;}
  if(Object.keys(q.patch).length||q.create){q.timer=setTimeout(()=>flush(key,sc,id),0);}
  else Q.delete(key);
  if(!Q.size)setStatus('saved');
}
function withPending(sc,id,d){
  const base=Object.assign({},d);
  const q=Q.get(sc+'|'+id);
  if(q)Object.assign(base,q.inflight||{},q.patch);
  return base;
}
function edit(sc,id,path,v){
  let doc=getLocal(sc,id);
  if(!doc){
    if(sc==='gl'||sc==='gn'||sc==='pl'||sc==='gp'||sc==='mg'||sc==='bt'||sc==='gb'||sc==='np'||sc==='bm'||sc==='sh'||sc==='sg'||sc==='cd'){doc={};putLocal(sc,id,doc);}
    else return;
  }
  const parts=path.split('.');
  const top=parts[0];
  const nv=setIn(doc[top],parts.slice(1),v);
  doc[top]=nv;
  save(sc,id,{[top]:nv});
  if(sc==='sg')shPubSoon();
  if(sc==='gt'&&(top==='name'||top==='place'))ntSyncRank(id);
  if(sc==='t'&&top==='badges')ntBadgeChanged();
}
function newDoc(sc,id,doc){putLocal(sc,id,doc);save(sc,id,doc,{create:true});}
async function removeDoc(sc,id){
  const key=sc+'|'+id;
  const q=Q.get(key);
  if(q){clearTimeout(q.timer);Q.delete(key);}
  dropLocal(sc,id);
  scheduleRender();
  try{
    await refFor(sc,id).delete();
    if(S.me.admin){
      if(sc==='p')await refFor('gl',id.slice(id.indexOf('/')+1)).delete();
      if(sc==='ppl')await refFor('gn',id).delete();
    }
  }catch(e){fail(e);}
}

/* ---------- live subscriptions ---------- */
let rq=0;
function scheduleRender(){if(rq)return;rq=requestAnimationFrame(()=>{rq=0;render();});}
function markReady(){if(!S.ready){S.ready=true;scheduleRender();}}
function snapMap(snap,sc,keep,prefix){
  const m={};
  snap.docs.forEach(d=>{m[d.id]=withPending(sc,(prefix||'')+d.id,d.data());});
  Object.keys(keep||{}).forEach(id=>{if(!(id in m)&&Q.has(sc+'|'+(prefix||'')+id))m[id]=keep[id];});
  return m;
}
function watch(query,onSnap,label){
  return query.onSnapshot(s=>{onSnap(s);scheduleRender();},e=>{console.warn(label,e&&e.code);markReady();});
}
const pokeSubs={};
function startWatches(){
  const db=S.db;
  watch(db.collection('trainers'),snap=>{
    S.trainers=snapMap(snap,'t',S.trainers);
    const have=new Set(Object.keys(S.trainers));
    have.forEach(uid=>{
      if(pokeSubs[uid])return;
      pokeSubs[uid]=db.collection('trainers').doc(uid).collection('pokemon').onSnapshot(s=>{
        S.pokemon[uid]=snapMap(s,'p',S.pokemon[uid],uid+'/');
        bmFogSoon();
        scheduleRender();
      },e=>console.warn('pokemon',e&&e.code));
    });
    Object.keys(pokeSubs).forEach(uid=>{
      if(!have.has(uid)){pokeSubs[uid]();delete pokeSubs[uid];delete S.pokemon[uid];}
    });
    markReady();
  },'trainers');
  watch(db.collection('people'),s=>{S.people=snapMap(s,'ppl',S.people);},'people');
  watch(db.collection('journal'),s=>{S.journal=snapMap(s,'j',S.journal);},'journal');
  watch(db.collection('leads'),s=>{S.leads=snapMap(s,'l',S.leads);},'leads');
  watch(db.collection('awards'),s=>{S.awards=snapMap(s,'aw',S.awards);},'awards');
  watch(db.collection('timeline'),s=>{S.timeline=snapMap(s,'tl',S.timeline);},'timeline');
  watch(db.collection('pins'),s=>{S.pins=snapMap(s,'pin',S.pins);},'pins');
  watch(db.collection('places'),s=>{S.places=snapMap(s,'pl',S.places);},'places');
  watch(db.collection('meta').doc('banner'),s=>{
    if(s.exists)S.banner=withPending('bn','banner',s.data());
    else if(!Q.has('bn|banner'))S.banner={};
  },'banner');
  watch(db.collection('meta').doc('conditions'),s=>{
    if(s.exists)S.cond=withPending('cd','conditions',s.data());
    else if(!Q.has('cd|conditions'))S.cond={};
  },'conditions');
  watch(db.collection('meta').doc('mega'),s=>{
    if(s.exists)S.megaOk=withPending('mg','mega',s.data());
    else if(!Q.has('mg|mega'))S.megaOk={};
  },'mega');
  watch(db.collection('meta').doc('battle'),s=>{
    if(s.exists)S.battle=withPending('bt','battle',s.data());
    else if(!Q.has('bt|battle'))S.battle={};
  },'battle');
  watch(db.collection('meta').doc('npcs'),s=>{
    if(s.exists)S.npcPub=withPending('np','npcs',s.data());
    else if(!Q.has('np|npcs'))S.npcPub={};
  },'npcs');
  watch(db.collection('meta').doc('shops'),s=>{
    if(s.exists)S.shopPub=withPending('sh','shops',s.data());
    else if(!Q.has('sh|shops'))S.shopPub={};
    shPubSoon();
  },'shops');
  watch(db.collection('meta').doc('bmap'),s=>{
    if(s.exists)S.bmap=withPending('bm','bmap',s.data());
    else if(!Q.has('bm|bmap'))S.bmap={};
    bmAssemble();
  },'bmap');
  watch(db.collection('meta').doc('pta_idx'),s=>{ptaSetIdx(s.exists?s.data():null);},'pta');
  watch(db.collection('mapimg'),s=>{
    const o={};
    s.docs.forEach(d=>{o[d.id]=d.data();});
    S.mapChunks=o;
    assembleMap();
    bmAssemble();
  },'mapimg');
  watch(db.collection('meta').doc('table'),s=>{
    if(s.exists)S.meta=Object.assign({},DEF_META,withPending('meta','table',s.data()));
    else if(!Q.has('meta|table'))S.meta=Object.assign({},DEF_META);
  },'meta');
  if(S.me.admin){
    watch(db.collection('gm'),s=>{
      const loy={},npc={},gpl={},gnt={},bch={};
      let gbat=null,gbm=null,gsh=null;
      s.docs.forEach(d=>{
        if(d.id==='battle')gbat=withPending('gb','battle',d.data());
        else if(d.id==='shops')gsh=withPending('sg','shops',d.data());
        else if(d.id==='bmap')gbm=withPending('bg','bmap',d.data());
        else if(d.id.indexOf('bmi_')===0)bch[+d.id.slice(4)]=d.data();
        else if(d.id.indexOf('loy_')===0)loy[d.id.slice(4)]=withPending('gl',d.id.slice(4),d.data());
        else if(d.id.indexOf('npc_')===0)npc[d.id.slice(4)]=withPending('gn',d.id.slice(4),d.data());
        else if(d.id.indexOf('place_')===0)gpl[d.id.slice(6)]=withPending('gp',d.id.slice(6),d.data());
        else if(d.id.indexOf('nt_')===0)gnt[d.id.slice(3)]=withPending('gt',d.id.slice(3),d.data());
      });
      Object.keys(S.gmPl).forEach(id=>{if(!(id in gpl)&&Q.has('gp|'+id))gpl[id]=S.gmPl[id];});
      Object.keys(S.gmLoy).forEach(id=>{if(!(id in loy)&&Q.has('gl|'+id))loy[id]=S.gmLoy[id];});
      Object.keys(S.gmNpc).forEach(id=>{if(!(id in npc)&&Q.has('gn|'+id))npc[id]=S.gmNpc[id];});
      Object.keys(S.gmNt).forEach(id=>{if(!(id in gnt)&&Q.has('gt|'+id))gnt[id]=S.gmNt[id];});
      S.gmLoy=loy;S.gmNpc=npc;S.gmPl=gpl;S.gmNt=gnt;
      if(gbat)S.battleGm=gbat;else if(!Q.has('gb|battle'))S.battleGm={};
      if(gbm)S.bmGm=gbm;else if(!Q.has('bg|bmap'))S.bmGm={};
      if(gsh)S.shopGm=gsh;else if(!Q.has('sg|shops'))S.shopGm={};
      shPubSoon();
      S.bmGmCh=bch;
      bmAssembleGm();
    },'gm');
  }
  if(CFG&&S.me.admin){
    /* the GM's library of saved battle maps: one small document each; their pictures are fetched only when one is used */
    watch(db.collection('config').where('kind','==','bscene'),s=>{
      const o={};
      s.docs.forEach(d=>{if(d.id.indexOf('bsc_')===0)o[d.id.slice(4)]=d.data();});
      S.bmLib=o;
    },'bscenes');
    watch(db.collection('config').doc('invite'),s=>{S.invite=s.exists?s.data():null;},'invite');
    watch(db.collection('members'),s=>{const m={};s.docs.forEach(d=>{m[d.id]=d.data();});S.members=m;},'members');
  }
  if(S.me.id){
    watch(db.doc('data/users/'+S.me.id+'/profile').collection('notes'),s=>{S.notes=snapMap(s,'n',S.notes);},'notes');
  }
}

async function startRoom(){
  const room=await use('room');
  if(!room)return;
  S.room=room;
  try{
    room.onPeers(ch=>{S.peers=ch.peers.filter(p=>p.kind==='viewer');renderHead();ensureNames();},()=>{});
    setPresence();
  }catch(e){}
}

